# The paste box: lines of name,amount,date,note, each a claim for the named person that arrives OPEN
# (added, or a matching DRAFT updated, then opened as the open button would). Every line is checked by
# the claim form's rules before any is added; one refused line, or one refused open, changes nothing.
validate:
  class: net.officefloor.hq.app.claim.ValidatePasteClaims
  next: snapshot
