snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SavePasteClaims
  govern: [ transaction ]
handle:
  class: net.officefloor.hq.app.claim.HandleInvalidClaim
